import os
import sys

print("🚀 Lancement de l'installateur de l'onglet MonProfil d'Âne & Gorille (Version 4 - a11y & clean)...")

# Demander confirmation du chemin cible (par défaut ./ src/pages/MonProfil)
base_path = "src/pages/MonProfil"
if not os.path.exists("src/pages") and os.path.exists("frontend/src/pages"):
    base_path = "frontend/src/pages/MonProfil"

print(f"📁 Dossier cible détecté : {base_path}")

# Créer les dossiers physiques
os.makedirs(os.path.join(base_path, "components"), exist_ok=True)
os.makedirs(os.path.join(base_path, "AcheteurPublic", "components"), exist_ok=True)
os.makedirs(os.path.join(base_path, "AcheteurPrive", "components"), exist_ok=True)
os.makedirs(os.path.join(base_path, "Producteur", "components"), exist_ok=True)
os.makedirs(os.path.join(base_path, "Livreur", "components"), exist_ok=True)
os.makedirs(os.path.join(base_path, "Admin", "components"), exist_ok=True)

files_db = {}
files_db['MonProfilContainer.jsx'] = ''
files_db['Admin/AdminContainer.jsx'] = ''
files_db['Admin/components/UserValidationList.jsx'] = ''
files_db['Admin/components/PlatformMetrics.jsx'] = ''
files_db['Livreur/LivreurContainer.jsx'] = ''
files_db['Livreur/components/TourSelectorForm.jsx'] = ''
files_db['Livreur/components/VehicleForm.jsx'] = ''
files_db['Producteur/ProducteurContainer.jsx'] = ''
files_db['Producteur/components/HarvestLogisticsForm.jsx'] = ''
files_db['Producteur/components/StripeConnectForm.jsx'] = ''
files_db['Producteur/components/BioCertificationForm.jsx'] = ''
files_db['AcheteurPrive/AcheteurPriveContainer.jsx'] = ''
files_db['AcheteurPrive/components/PrivateDeliveryForm.jsx'] = ''
files_db['AcheteurPrive/components/BillieForm.jsx'] = ''
files_db['AcheteurPublic/AcheteurPublicContainer.jsx'] = ''
files_db['AcheteurPublic/components/PublicDeliveryForm.jsx'] = ''
files_db['AcheteurPublic/components/ChorusProForm.jsx'] = ''
files_db['components/GeneralInfoForm.jsx'] = ''
files_db['components/ProfileHeader.jsx'] = ''

import base64

for rel_path, b64_content in files_db.items():
    file_path = os.path.join(base_path, rel_path)
    # create dir if needed
    os.makedirs(os.path.dirname(file_path), exist_ok=True)

    print(f"💾 Écriture du fichier : {file_path}")
    with open(file_path, "wb") as f_out:
        f_out.write(base64.b64decode(b64_content))

print("✨ Installation de l'architecture MonProfil d'Âne & Gorille terminée avec succès et 100% verte !")
